I paste a minimal example here:
```python
import numpy as np
import gradio as gr

head = '<script src="https://3Dmol.org/build/3Dmol-min.js"></script>'
def style(div):
    return f'<div id="{div}" style="height: 400px; width: 400px; position: relative;"></div>'

def js_on_load(viewer, div):
    return f"""
let {viewer} = null;
const render_{viewer} = () => {{
    if (!{viewer}) {{
        {viewer} = $3Dmol.createViewer(
            element.querySelector('#{div}'), 
            {{backgroundColor: 'white'}});
    }}
    {viewer}.clear();
    $3Dmol.download('pdb:' + props.value, {viewer}, {{}}, () => {{
        {viewer}.setStyle({{}}, {{stick: {{}}}});
        {viewer}.zoomTo();
        {viewer}.render();
    }});
}};
render_{viewer}();
watch('value', render_{viewer});
"""

def on_random_click():
    return gr.update(value=np.random.choice(["2POR", "5CXT", "6QVT"]))

with gr.Blocks() as demo:
    with gr.Row(equal_height=True):
        with gr.Column():
            viewerl = gr.HTML(head=head, 
                              js_on_load=js_on_load("viewer_l", "mol_l"), 
